    "chapterKey": "ff-prose-03",
    "title": "Chapter 3: Two Stories about Flying",
    "author": "Liam O'Flaherty & Frederick Forsyth",
    "bookName": "First Flight — Prose",
    "pdfPath": "/ncert/english/jeff103.pdf",
